"""Question-specific drafting tasks, never legal facts or test expectations."""
import re
from response_guidance import is_document_request


def drafting_focus(question, previous, evidence):
    current = question.split('\nПредыдущий вопрос:')[0]
    context = current + '\n' + (previous or '')
    documents = {p.get('document_id') for p in evidence}
    tasks = []
    if 'credit-history' in documents and re.search(r'кредитн.{0,20}(?:истори|отч[её]т)|бюро|погашенн.{0,20}(?:кредит|за[её]м)', context, re.I):
        if is_document_request(current):
            tasks.append('Подготовь само заявление о проверке спорной записи: Кому, От, какая запись оспаривается, что проверить/исправить, перечень подтверждений, Дата и Подпись. Используй заполнители вместо личных данных. Просьбы не выдавай за гарантированный результат; достоверную историю не обещай удалить.')
        elif re.search(r'ошиб|неверн|недостовер|исправ|оспор|погаш|закрыт|просроч', current, re.I):
            tasks.append('Раздели спорную запись и доказательства её ошибочности, адресата проверки — бюро или поставщика сведений по переданным нормам — и запрос письменного результата. Не обещай автоматическое исправление или удаление всей кредитной истории.')
        elif re.search(r'получ|узна|скача|заказ|посмотр', current, re.I):
            tasks.append('Ответь о получении отчёта о себе: предложи официальный канал бюро или государственной услуги без непроверенной ссылки, объясни безопасную проверку личности через этот канал. Не проси присылать пароль, код или полный отчёт в чат. Не добавляй спор об ошибке, если его не спрашивали.')
    if ('collectors' in documents and re.search(r'чуж|родственник|знаком', current, re.I)
            and not re.search(r'угроз|насили', current, re.I)):
        tasks.append('Раздели контакт с третьим лицом и требование оплатить долг. Предложи запросить основание требования и проверить, какую роль в договоре приписывают пользователю; не выводи его обязанность или её отсутствие только из родства.')
    if 'shared-construction' in documents and re.search(r'документ|провер|каки.{0,15}способ', current, re.I):
        tasks.append('Сопоставь запрошенные документы с конкретным способом привлечения денег, описанным в источниках. Различай сведения о гарантии и разрешение там, где они предусмотрены; не требуй одновременно одинаковый комплект для любых схем. Предложи запросить название компании и способ привлечения денег без перевода оплаты до проверки.')
    if 'auto-insurance' in documents and re.search(r'удерж|выч[её]л|вычет|оценк.{0,20}расход|расход.{0,20}оценк', current, re.I):
        tasks.append('Разбери именно удержание из выплаты: предложи запросить расчёт и название удержанных расходов. Отдели собственные расходы страховщика на определение ущерба от иных возможных платежей. Правовую оценку дай только по соответствующей переданной норме, не по общему описанию страхового случая.')
    if 'joint-stock' in documents and re.search(r'дивиденд|доход|распределен', current, re.I):
        tasks.append('Сначала установи вид акций: общее описание решения по выплате не переноси автоматически на привилегированные акции. Сохрани отдельно подтверждённые условия и ограничения из источников; не перечисляй ненужные числовые сроки.')
    if 'digital-assets' in documents and re.search(r'отлич|разниц|сравн|вид[ыа]', current, re.I):
        tasks.append('Дай сравнение названных категорий по определениям из переданной редакции. Если термин в вопросе и термин в действующем фрагменте различаются, обозначь это различие, не подменяя одну классификацию другой. Не обещай доходность, гарантии государства или разрешённость любой площадки.')
    return tasks
